<script setup lang="ts">
import { BookOpen, Layers3 } from '@lucide/vue'; import type { Enrollment, Student } from '~/types/domain'
interface Data { kind: string; student: Student; enrollments: Enrollment[]; current_units: number }
const { user } = useAuth(); const { get } = useDashboard<Data>(); const { data } = await useAsyncData('student-dashboard', get)
const stats = computed(() => [{ label: 'Enrolled Courses', value: data.value?.enrollments.length ?? 0, detail: 'Current load', icon: BookOpen }, { label: 'Current Units', value: data.value?.current_units ?? 0, detail: 'Current load', icon: Layers3 }])
</script>
<template><div class="space-y-6"><BaseCard class="bg-[#102a43] text-white"><p class="text-sm text-blue-200">Student record</p><h2 class="mt-1 text-2xl font-semibold tracking-[-0.025em]">Hello, {{ user?.name.split(' ')[0] }}</h2><p class="mt-4 border-t border-white/15 pt-4 text-sm text-blue-100">{{ data?.student.student_number }} · {{ data?.student.program?.code }} · Year {{ data?.student.year_level }}</p></BaseCard><div class="metric-grid grid sm:grid-cols-2"><StatCard v-for="stat in stats" :key="stat.label" v-bind="stat" /></div><BaseCard><h2 class="mb-3 text-lg font-semibold tracking-[-0.02em] text-[#102a43]">Current courses</h2><div v-for="enrollment in data?.enrollments" :key="enrollment.id" class="border-t border-[#e5ecf3] py-4"><p class="font-semibold text-[#29445f]">{{ enrollment.course_offering?.course?.course_code }} · {{ enrollment.course_offering?.course?.course_title }}</p><p class="mt-0.5 text-sm text-[#60728a]">{{ enrollment.course_offering?.section }}</p></div></BaseCard></div></template>
